<script lang="ts">
 import {command} from '#lib/client/api.ts';import type {Row} from '#lib/client/types.ts';
 let {oncreated}:{oncreated:(customer:Row)=>void}=$props();let open=$state(false),name=$state(''),email=$state(''),phone=$state(''),busy=$state(false),error=$state('');
 async function save(){if(busy)return;error='';if(name.trim().length<2){error='Bitte den Namen oder die Firma mit mindestens zwei Zeichen angeben.';return;}busy=true;try{const customer=await command('crm.customer.create',undefined,{name:name.trim(),...(email?{email}:{}),...(phone?{phone}:{})});oncreated(customer);open=false;name='';email='';phone='';}catch(cause){error=cause instanceof Error?cause.message:'Der Kunde konnte nicht angelegt werden.';}finally{busy=false;}}
</script>
<div class="quick-customer">{#if !open}<button type="button" class="text-link" onclick={()=>open=true}>+ Neuen Kunden direkt anlegen</button>{:else}<fieldset disabled={busy}><legend>Neuer Kunde · Anfrage bleibt erhalten</legend>{#if error}<p class="field-error" role="alert">{error}</p>{/if}<label>Name / Firma *<input bind:value={name} autocomplete="organization"/></label><label>E-Mail · optional<input bind:value={email} type="email" autocomplete="email"/></label><label>Telefon · optional<input bind:value={phone} autocomplete="tel"/></label><div class="inline-actions mt"><button type="button" class="btn primary small" onclick={save}>{busy?'Wird gespeichert …':'Kunden anlegen & auswählen'}</button><button type="button" class="btn small" onclick={()=>open=false}>Abbrechen</button></div></fieldset>{/if}</div>
<style>.quick-customer{grid-column:1/-1}.quick-customer fieldset{padding:16px;border:1px solid var(--line);border-radius:10px;background:var(--wash)}legend{font-size:13px;padding:0 6px}label{display:block;font-size:12px;margin-top:12px}input{display:block;width:100%;margin-top:6px}</style>
